<script setup lang="ts">import{reactive,ref}from'vue';import{api}from'../../api';const saving=ref(false),form=reactive({buildingName:'西区 6 栋',floor:3,room:'318',contactName:'小橙',phone:'13800132026'});async function save(){if(!form.buildingName||!form.room||!form.contactName||!/^1\d{10}$/.test(form.phone)){uni.showToast({title:'请完整填写寝室与手机号',icon:'none'});return}saving.value=true;try{await api.addAddress({...form});uni.showToast({title:'地址已保存',icon:'success'});setTimeout(()=>uni.navigateBack(),500)}finally{saving.value=false}}</script>
<template><view class="page"><view class="campus card"><text class="campus__label">配送学校</text><text class="campus__name">湖北工业大学</text><text class="muted">当前试点校园，不可切换</text></view><view class="form card"><label><text>宿舍楼栋</text><input v-model="form.buildingName" placeholder="例如：西区 6 栋"/></label><label><text>所在楼层</text><input v-model.number="form.floor" type="number" placeholder="楼层"/></label><label><text>寝室号</text><input v-model="form.room" type="number" placeholder="例如：318"/></label><label><text>联系人</text><input v-model="form.contactName" placeholder="你的称呼"/></label><label><text>手机号</text><input v-model="form.phone" type="number" maxlength="11" placeholder="用于配送联系"/></label></view><button class="primary-btn" :disabled="saving" @tap="save">{{saving?'正在保存…':'保存寝室地址'}}</button></view></template>
<style scoped lang="scss">@import '../../styles/theme.scss';.campus,.form{padding:28rpx}.campus__label,.campus__name{display:block}.campus__label{color:$primary-dark;font-size:22rpx;font-weight:800}.campus__name{font-size:36rpx;font-weight:900;margin:10rpx 0}.form{margin-top:24rpx}.form label{display:block;padding:22rpx 0;border-bottom:2rpx solid $line}.form label:last-child{border:none}.form label>text{display:block;font-size:23rpx;color:$muted;margin-bottom:12rpx}.form input{height:60rpx;font-size:30rpx;font-weight:700}.primary-btn{margin-top:34rpx}</style>
